import React, { useState, useEffect } from "react";
// import { ThemeProvider } from "@mui/material/styles";
import CssBaseline from "@mui/material/CssBaseline";
import Box from "@mui/material/Box";
import Container from "@mui/material/Container";
import Grid from "@mui/material/Grid";
import Paper from "@mui/material/Paper";
import List from "@mui/material/List";
import ListItem from "@mui/material/ListItem";
import ListItemText from "@mui/material/ListItemText";
import ListItemIcon from "@mui/material/ListItemIcon";
import Typography from "@mui/material/Typography";
import Circle from "@mui/icons-material/Circle";
import BookmarkIcon from "@mui/icons-material/Bookmark";
import AccessTimeIcon from "@mui/icons-material/AccessTime";
import CommentIcon from "@mui/icons-material/Comment";
import Dialog from "@mui/material/Dialog";
import DialogActions from "@mui/material/DialogActions";
import DialogContent from "@mui/material/DialogContent";
import DialogContentText from "@mui/material/DialogContentText";
import DialogTitle from "@mui/material/DialogTitle";
import Button from "@mui/material/Button";
import { useNavigate } from "react-router-dom";
import {
  deleteUser,
  onAuthStateChanged,
  reauthenticateWithPopup,
  GoogleAuthProvider,
} from "firebase/auth";
import { auth } from "../firebase";
import Cookies from "js-cookie";
import { deleteWordPressAccount, fetchWordPressSession } from "../services/authApi";
import { mapAuthApiErrorMessage } from "../utils/authApiErrors";
import TextField from "@mui/material/TextField";
import Alert from "@mui/material/Alert";
import LinearProgress from "@mui/material/LinearProgress";
import CircularProgress from "@mui/material/CircularProgress";
import Snackbar from "@mui/material/Snackbar";
import Chip from "@mui/material/Chip";
import CheckCircleOutline from "@mui/icons-material/CheckCircleOutline";
import RefreshIcon from "@mui/icons-material/Refresh";
import PublishedWithChangesIcon from "@mui/icons-material/PublishedWithChanges";
import PauseIcon from "@mui/icons-material/Pause";
import ManageAccountsIcon from "@mui/icons-material/ManageAccounts";
import Footer from "../components/Footer/Footer";
import SubscriptionStatus from "../components/Subscription/SubscriptionStatus";

function AccountContent({
  loggedIn,
  user,
  setUser,
}: {
  loggedIn: boolean;
  user: any;
  setUser: any;
}) {
  const [checked, setChecked] = useState<string[]>([]);
  const [openDialog, setOpenDialog] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  // const [userId, setUserId] = useState<number | null>(null);
  const userId = Cookies.get("userId");
  const [deleteStep, setDeleteStep] = useState<
    "initial" | "verify" | "export" | "deleting"
  >("initial");
  const [error, setError] = useState<string | null>(null);
  const [snackbar, setSnackbar] = useState<{
    open: boolean;
    message: string;
    severity: "success" | "error" | "info";
  }>({
    open: false,
    message: "",
    severity: "info",
  });
  const [userDebugInfo, setUserDebugInfo] = useState<any>(null);
  const [isDebugLoading, setIsDebugLoading] = useState(false);
  const navigate = useNavigate();

  const deleteDebug = process.env.USER_DELETE_DEBUG;

  // console.log("Config check:", {
  //   deleteDebug,
  // });

  const showError = (message: string) => {
    setError(message);
    setSnackbar({ open: true, message, severity: "error" });
  };

  const handleConfirmDelete = async () => {
    setIsDeleting(true);
    setError(null);

    try {
      setDeleteStep("verify");

      if (!user) {
        throw new Error("You must be signed in to delete your account.");
      }

      // Export user data for GDPR compliance (mock step)
      setDeleteStep("export");
      await new Promise((resolve) => setTimeout(resolve, 1000));

      setDeleteStep("deleting");

      await deleteWordPressAccount(user);
      try {
        await deleteUser(user);
      } catch (firebaseError: any) {
        console.log("Firebase deletion error:", firebaseError);

        if (firebaseError.code === "auth/requires-recent-login") {
          // console.log("Requiring reauthentication...");
          try {
            const provider = new GoogleAuthProvider();
            await reauthenticateWithPopup(user, provider);
            await deleteUser(user);
            // console.log("Firebase user deleted after reauthentication");
          } catch (reAuthError: any) {
            console.error("Reauthentication failed:", reAuthError);
            throw new Error(
              "Failed to authenticate for account deletion. Please sign out and try again."
            );
          }
        } else {
          console.error("Unknown Firebase error:", firebaseError);
          throw firebaseError;
        }
      }

      // Step 3: Clear cookies and redirect
      const cookies = Cookies.get();
      for (const cookie in cookies) {
        Cookies.remove(cookie);
      }

      setUser(null);
      navigate("/");
      setSnackbar({
        open: true,
        message: "Your account has been successfully deleted.",
        severity: "success",
      });
    } catch (error: unknown) {
      console.error("Delete error:", error);
      showError(
        mapAuthApiErrorMessage(error, "Failed to delete account")
      );
      setDeleteStep("initial");
    } finally {
      setIsDeleting(false);
      setOpenDialog(false); // Close dialog after completion or error
    }
  };

  const handleToggle = (value: string) => () => {
    const currentIndex = checked.indexOf(value);
    const newChecked = [...checked];

    if (currentIndex === -1) {
      newChecked.push(value);
    } else {
      newChecked.splice(currentIndex, 1);
    }

    setChecked(newChecked);
  };

  const handleDelete = async () => {
    setOpenDialog(true);
  };

  const checkUserPermissions = async () => {
    if (deleteDebug !== "true") {
      return;
    }

    setIsDebugLoading(true);
    setError(null);

    try {
      if (!user) {
        throw new Error("You must be signed in to check permissions.");
      }

      const session = await fetchWordPressSession(user);
      setUserDebugInfo({
        ID: session.wpUserId,
        user_login: session.email,
        display_name: user.displayName ?? session.email,
        roles: session.wpUserExists ? ["subscriber"] : [],
        has_delete_self: session.wpUserExists,
        capabilities: {},
      });

      setSnackbar({
        open: true,
        message: session.wpUserExists
          ? "WordPress account linked for this Firebase user"
          : "No WordPress account linked for this Firebase user",
        severity: session.wpUserExists ? "info" : "error",
      });
    } catch (error: unknown) {
      const message =
        error instanceof Error ? error.message : "Failed to fetch user permissions";
      console.error("Error fetching user debug info:", error);
      setUserDebugInfo({ error: message });
      showError(message);
    } finally {
      setIsDebugLoading(false);
    }
  };

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
    });
    return () => unsubscribe();
  }, [setUser]);

  return (
    <>
    <Box sx={{ display: "flex", marginTop: "15px", fontFamily: "Quicksand" }}>
        <CssBaseline />
        {/* sidebar */}
        <Box
          component="main"
          sx={{
            mt: 5,
            backgroundColor: (theme) =>
              theme.palette.mode === "dark" ? "#212121" : "#FFFFFF",
            flexGrow: 1,
            height: "100vh", 
            overflow: "auto",
          }}
        >
          <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
            <Grid container spacing={3}>
              <Grid item xs={12}>
                <Paper
                  sx={{
                    px: { xs: 2, sm: 8, md: 8 },
                    py: 8,
                    display: "flex",
                    width: "100%",
                    position: "relative",
                    height: "auto",
                    fontFamily: "Quicksand",
                  }}
                  elevation={4}
                >
                  <Grid container spacing={3} sx={{ textAlign: "left" }}>
                    <Grid item xs={12} md={12} sx={{ textAlign: "right" }}>
                      {/* user api */}
                      <List
                        sx={{
                          width: "100%",
                          maxHeight: 360,
                          bgcolor: "background.transparent",
                          marginTop: "1rem",
                          float: "left",
                        }}
                      >
                        <ListItem alignItems="flex-start">
                          {
                            <img
                              style={{
                                width: 48,
                                height: 48,
                                borderRadius: 5,
                                marginBottom: 10,
                              }}
                              alt={user?.displayName || "User"}
                              src={`${user?.photoURL}`}
                            />
                          }
                          <div style={{ borderRadius: 0 }}>
                            <Typography
                              sx={{
                                marginLeft: 2,
                                mt: 1,
                                fontSize: "0.75rem",
                                fontWeight: 600,
                                color: (theme) =>
                                  theme.palette.mode === "dark" ? "#A1A1A1" : "#000000",
                              }}
                            >
                              {user && user?.displayName}
                            </Typography>
                            <Typography
                              sx={{
                                marginLeft: 2,
                                mt: -1,
                                fontSize: "0.65rem",
                                fontWeight: 400,
                                color: "white",
                                display: "flex",
                                alignItems: "center",
                              }}
                            >
                              <Circle
                                sx={{ width: 10 }}
                                htmlColor={"#02b548"}
                              />
                              &nbsp;Active
                            </Typography>
                          </div>
                        </ListItem>
                      </List>
                    </Grid>
                    <Grid
                      item
                      xs={12}
                      sm={12}
                      md={6}
                      sx={{
                        display: "flex",
                        flexDirection: "column",
                        alignItems: "flex-start",
                      }}
                    >
                      <Box sx={{ mb: 3, minWidth: "100%", mt: 2 }}>
                        <Typography variant="h6" gutterBottom align="left">
                          What's included in your subscription:
                        </Typography>
                        <List
                          sx={{
                            width: "100%",
                            maxWidth: "100%",
                          }}
                        >
                          <ListItem>
                            <ListItemIcon>
                              <CommentIcon color="primary" />
                            </ListItemIcon>
                            <ListItemText
                              primary="Comments"
                              secondary="Share your insights and discuss scriptures with others"
                            />
                          </ListItem>
                          <ListItem>
                            <ListItemIcon>
                              <BookmarkIcon color="primary" />
                            </ListItemIcon>
                            <ListItemText
                              primary="Premium Features"
                              secondary="Access to all current and future premium features"
                            />
                          </ListItem>
                          <ListItem>
                            <ListItemIcon>
                              <AccessTimeIcon color="primary" />
                            </ListItemIcon>
                            <ListItemText
                              primary="Priority Support"
                              secondary="Get help quickly when you need it"
                            />
                          </ListItem>
                        </List>
                      </Box>

                      <Box
                        sx={{
                          display: "flex",
                          justifyContent: "center",
                          gap: 2,
                          mt: 4,
                          marginLeft: "50%",
                          transform: "translateX(-50%)",
                        }}
                      >
                        <Button
                          href="https://billing.stripe.com/p/login/00g14P1th6YseVaaEE"
                          target="_blank"
                          variant="contained"
                          color="secondary"
                          size="small"

                        >
                          Manage Subscription
                        </Button>
                      </Box>
                    </Grid>
                    <Grid
                      item
                      xs={12}
                      md={6}
                      sx={{
                        display: "flex",
                        flexDirection: "column",
                        alignItems: "flex-end",
                      }}
                    >
                      {/* <Typography
                        sx={{
                          display: "block",
                          textAlign: "center",
                          width: "auto",
                        }}
                        component="span"
                        color="text.primary"
                      >
                        SUBSCRIPTIONS
                      </Typography> */}

                      {/* SUBSCRIPTION SQUARE BLOCK */}

                      <Box sx={{ mb: 3, minWidth: "100%", mt: 2 }}>
                        <SubscriptionStatus />
                      </Box>

                      <List
                        sx={{
                          marginTop: "1rem",
                          width: "100%",
                          bgcolor: "background.transparent",
                          float: "center",
                        }}
                      >
                        {/* <ListItem>
                          <ListItemIcon>
                            <PublishedWithChangesIcon />
                          </ListItemIcon>
                          <ListItemText
                            id="switch-list-label-auto-renew"
                            primary="Auto Renew"
                          />
                          <Switch
                            edge="end"
                            color="default"
                            inputProps={{
                              "aria-labelledby": "switch-list-label-auto-renew",
                            }}
                          />
                        </ListItem>
                        <ListItem>
                          <ListItemIcon>
                            <PauseIcon />
                          </ListItemIcon>
                          <ListItemText
                            id="switch-list-label-pause-membership"
                            primary="Pause Membership"
                          />
                          <Switch
                            edge="end"
                            color="default"
                            inputProps={{
                              "aria-labelledby": "switch-list-label-pause-membership",
                            }}
                          />
                        </ListItem>
                        <ListItem>
                          <ListItemIcon>
                            <ManageAccountsIcon />
                          </ListItemIcon>
                          <ListItemText
                            id="switch-list-label-freemium"
                            primary="Freemium"
                          />
                          <Switch
                            edge="end"
                            color="default"
                            inputProps={{
                              "aria-labelledby": "switch-list-label-freemium",
                            }}
                          />
                        </ListItem> */}
                        {/* <ListItem>
                          <ListItemIcon>
                          </ListItemIcon>
                          <ListItemText
                            id="switch-list-label-links"
                            primary="Public Account"
                          />
                          <Switch
                            edge="end"
                            color="default"
                            onChange={handleToggle("links")}
                            checked={checked.indexOf("links") !== -1}
                            inputProps={{
                              "aria-labelledby": "switch-list-label-links",
                            }}
                          />
                        </ListItem> */}
                      </List>
                    </Grid>
                  </Grid>
                </Paper>
              </Grid>

              {/* Recent Orders */}
              <Grid item xs={12} md={12}>
                <Paper
                  onClick={handleDelete}
                  sx={{
                    p: 2,
                    display: "flex",
                    flexDirection: "column",
                    backgroundColor: "#BB000000",
                    cursor: "pointer",
                    fontFamily: "Comfortaa",
                    "&:hover": {
                      backgroundColor: "#990000",
                    },
                  }}
                  elevation={4}
                >
                  <Typography>DELETE ACCOUNT</Typography>
                </Paper>
              </Grid>
              {deleteDebug === "true" && (
                <Grid item xs={12}>
                  <Box
                    sx={{
                      p: 2,
                      display: "flex",
                      flexDirection: "column",
                      backgroundColor: "#f5f5f5",
                      borderRadius: 1,
                      mb: 2,
                    }}
                  >
                    <Typography variant="h6" sx={{ mb: 2 }}>
                      User Permission Debug
                    </Typography>
                    {isDebugLoading ? (
                      <Box sx={{ display: "flex", alignItems: "center" }}>
                        <CircularProgress size={20} sx={{ mr: 2 }} />
                        <Typography>Loading user information...</Typography>
                      </Box>
                    ) : userDebugInfo?.error ? (
                      <Alert severity="error" sx={{ mb: 2 }}>
                        {userDebugInfo.error}
                      </Alert>
                    ) : userDebugInfo ? (
                      <Box>
                        <Grid container spacing={2}>
                          <Grid item xs={12} sm={6}>
                            <Paper sx={{ p: 2 }}>
                              <Typography
                                variant="subtitle1"
                                sx={{ fontWeight: "bold", mb: 1 }}
                              >
                                User Information
                              </Typography>
                              <Typography>
                                <strong>User ID:</strong> {userDebugInfo.ID}
                              </Typography>
                              <Typography>
                                <strong>Username:</strong>{" "}
                                {userDebugInfo.user_login}
                              </Typography>
                              <Typography>
                                <strong>Display Name:</strong>{" "}
                                {userDebugInfo.display_name}
                              </Typography>
                              <Typography>
                                <strong>Roles:</strong>{" "}
                                {userDebugInfo.roles?.join(", ") || "None"}
                              </Typography>
                              <Typography sx={{ mt: 1 }}>
                                <strong>Can Delete Self:</strong>{" "}
                                {userDebugInfo.has_delete_self ? (
                                  <Chip
                                    size="small"
                                    label="Yes"
                                    color="success"
                                  />
                                ) : (
                                  <Chip size="small" label="No" color="error" />
                                )}
                              </Typography>
                            </Paper>
                          </Grid>
                          <Grid item xs={12} sm={6}>
                            <Paper sx={{ p: 2, height: "100%" }}>
                              <Typography
                                variant="subtitle1"
                                sx={{ fontWeight: "bold", mb: 1 }}
                              >
                                Capabilities
                              </Typography>
                              {userDebugInfo.capabilities &&
                              typeof userDebugInfo.capabilities === "object" ? (
                                <Box
                                  sx={{ maxHeight: "200px", overflow: "auto" }}
                                >
                                  <List dense>
                                    {Object.keys(userDebugInfo.capabilities)
                                      .filter(
                                        (cap) =>
                                          userDebugInfo.capabilities[cap] ===
                                          true
                                      )
                                      .map((cap) => (
                                        <ListItem key={cap} disablePadding>
                                          <ListItemIcon
                                            sx={{ minWidth: "35px" }}
                                          >
                                            <CheckCircleOutline
                                              fontSize="small"
                                              color="success"
                                            />
                                          </ListItemIcon>
                                          <ListItemText primary={cap} />
                                        </ListItem>
                                      ))}
                                  </List>
                                </Box>
                              ) : (
                                <Typography>No capabilities found</Typography>
                              )}
                            </Paper>
                          </Grid>
                        </Grid>

                        <Box
                          sx={{
                            mt: 2,
                            display: "flex",
                            justifyContent: "flex-end",
                          }}
                        >
                          <Button
                            variant="outlined"
                            size="small"
                            color="primary"
                            onClick={checkUserPermissions}
                            startIcon={<RefreshIcon />}
                          >
                            Refresh Debug Info
                          </Button>
                        </Box>
                      </Box>
                    ) : (
                      <Typography>No user information available</Typography>
                    )}
                  </Box>
                </Grid>
              )}
            </Grid>
          </Container>
        </Box>
      </Box>
      <Box>
      <Dialog
        open={openDialog}
        onClose={() => !isDeleting && setOpenDialog(false)}
      >
        <DialogTitle sx={{ color: "#BB0000" }}>Delete Account</DialogTitle>
        <DialogContent>
          <Box sx={{ width: "100%", mb: 2 }}>
            <LinearProgress
              variant="determinate"
              value={
                deleteStep === "initial"
                  ? 0
                  : deleteStep === "verify"
                  ? 25
                  : deleteStep === "export"
                  ? 50
                  : deleteStep === "deleting"
                  ? 75
                  : 100
              }
            />
          </Box>
          {deleteStep === "initial" && (
            <>
              <DialogContentText>
                Are you sure you want to delete your account? This action cannot
                be undone.
              </DialogContentText>
            </>
          )}
          {deleteStep === "verify" && (
            <DialogContentText>
              Verifying WordPress credentials...
            </DialogContentText>
          )}
          {deleteStep === "export" && (
            <DialogContentText>
              Exporting your data for GDPR compliance...
            </DialogContentText>
          )}
          {deleteStep === "deleting" && (
            <DialogContentText>Deleting your account...</DialogContentText>
          )}
          {error && (
            <Alert severity="error" sx={{ mt: 2 }}>
              {error}
            </Alert>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenDialog(false)} disabled={isDeleting}>
            Cancel
          </Button>
          <Button
            onClick={handleConfirmDelete}
            color="error"
            variant="contained"
            autoFocus
            disabled={isDeleting}
            sx={{
              backgroundColor: "#BB0000",
              "&:hover": {
                backgroundColor: "#990000",
              },
            }}
          >
            {isDeleting ? (
              <CircularProgress size={24} color="inherit" />
            ) : deleteStep === "initial" ? (
              "Delete Account"
            ) : deleteStep === "verify" ? (
              "Verify & Continue"
            ) : deleteStep === "export" ? (
              "Exporting..."
            ) : (
              "Deleting..."
            )}
          </Button>
        </DialogActions>
      </Dialog>

      {/* <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={() => setSnackbar(prev => ({ ...prev, open: false }))}
      >
        <Alert severity={snackbar.severity} onClose={() => setSnackbar(prev => ({ ...prev, open: false }))}>
          {snackbar.message}
        </Alert>
      </Snackbar> */}
    </Box>
    </>
  );
}

export default function Account({
  loggedIn,
  user,
  setUser,
}: {
  loggedIn: boolean;
  user: any;
  setUser: any;
}) {
  return <AccountContent loggedIn={loggedIn} user={user} setUser={setUser} />;
}
