/**
 * Verse Mapping System - Central Index
 * 
 * This module provides a centralized interface for verse mappings between translations.
 * Each translation has its own mapping file (e.g., cuvToKjv.ts).
 * 
 * To add a new translation:
 * 1. Create a new mapping file (e.g., esvToKjv.ts)
 * 2. Export the mapping and helper functions
 * 3. Import and register it here
 */

import { 
  getKjvVerseFromCuv, 
  hasCuvToKjvMapping,
  type BookMapping as CuvBookMapping 
} from './cuvToKjv';

import {
  getKjvVerseFromLut,
  hasLutToKjvMapping,
  type BookMapping as LutBookMapping
} from './lutToKjv';

export type TranslationCode = 'cuv' | 'kjv' | 'lut' | 'esv' | 'niv' | string;

export interface VerseMappingResult {
  kjvVerse: number;
  hasMapping: boolean;
}

/**
 * Get KJV verse number from any translation's verse number
 * 
 * IMPORTANT: This function ONLY applies mappings when translation is 'cuv' or 'lut'.
 * When translation is 'kjv' (default), it returns the verse number as-is (no mapping).
 * 
 * @param fromTranslation - Source translation code ('cuv', 'lut', or 'kjv')
 * @param book - Bible book name
 * @param chapter - Chapter number
 * @param verse - Verse number in source translation
 * @returns KJV verse number, or original verse if no mapping exists or translation is 'kjv'
 */
export const getKjvVerseFromTranslation = (
  fromTranslation: TranslationCode,
  book: string,
  chapter: number,
  verse: number
): VerseMappingResult => {
  // If already KJV (default), no conversion needed - return verse number as-is
  if (fromTranslation === 'kjv') {
    return { kjvVerse: verse, hasMapping: false };
  }
  
  // Apply mapping when translation is 'cuv'
  if (fromTranslation === 'cuv') {
    const kjvVerse = getKjvVerseFromCuv(book, chapter, verse);
    if (kjvVerse !== null) {
      return { kjvVerse, hasMapping: true };
    }
    // If no specific mapping found, fallback to verse number as-is
    return { kjvVerse: verse, hasMapping: false };
  }
  
  // Apply mapping when translation is 'lut'
  if (fromTranslation === 'lut') {
    const kjvVerse = getKjvVerseFromLut(book, chapter, verse);
    if (kjvVerse !== null) {
      return { kjvVerse, hasMapping: true };
    }
    // If no specific mapping found, fallback to verse number as-is
    return { kjvVerse: verse, hasMapping: false };
  }
  
  // Add other translation mappings here as they're added
  // if (fromTranslation === 'esv') {
  //   return getKjvVerseFromEsv(book, chapter, verse);
  // }
  
  // Default: assume verse numbers align (no mapping needed)
  // This handles cases where translation might be undefined or unknown
  return { kjvVerse: verse, hasMapping: false };
};

/**
 * Check if a translation has verse mappings to KJV
 */
export const hasTranslationMapping = (
  translation: TranslationCode,
  book: string,
  chapter: number
): boolean => {
  if (translation === 'kjv') {
    return false;
  }
  
  if (translation === 'cuv') {
    return hasCuvToKjvMapping(book, chapter);
  }
  
  if (translation === 'lut') {
    return hasLutToKjvMapping(book, chapter);
  }
  
  // Add checks for other translations as they're added
  return false;
};

/**
 * Generate a verse slug using KJV numbering (for WordPress post alignment)
 * This ensures comments can be found regardless of which translation was used
 * 
 * IMPORTANT: 
 * - When translation is 'cuv': Converts CUV verse number to KJV using mapping
 * - When translation is 'lut': Converts LUT verse number to KJV using mapping
 * - When translation is 'kjv' (default): Uses verse number directly (no conversion)
 * 
 * @param book - Bible book name
 * @param chapter - Chapter number
 * @param verse - Verse number (in source translation)
 * @param translation - Source translation code ('cuv', 'lut', or 'kjv')
 * @returns Slug string like "psalms-23-1" (always uses KJV numbering for WordPress posts)
 */
export const generateKjvVerseSlug = (
  book: string,
  chapter: number,
  verse: number,
  translation: TranslationCode = 'kjv'
): string => {
  // If translation is 'kjv', verse number is used as-is (no mapping)
  // If translation is 'cuv' or 'lut', verse number is converted to KJV using mapping
  const { kjvVerse } = getKjvVerseFromTranslation(translation, book, chapter, verse);
  return `${book.trim()}-${chapter}-${kjvVerse}`;
};

